// Generates themes/helder.yaml from the token definitions (default settings).
// The bundle overrides these values at runtime with the settings stored in HA.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { computeTokens, haVariables } from '../src/tokens/tokens';
import { DEFAULT_SETTINGS, type Mode } from '../src/tokens/settings';

const q = (v: string) => `'${v.replace(/'/g, "''")}'`;

export function themeYaml(): string {
  const lines = [
    '# Generated by scripts/gen-theme.ts from src/tokens. Do not edit by hand.',
    '# Default values; helder.js applies the settings from the Helder settings page on top of these.',
    'helder:',
    `  helder-theme-active: '1'`,
    '  modes:',
  ];
  for (const mode of ['light', 'dark'] as Mode[]) {
    const t = computeTokens(DEFAULT_SETTINGS, mode);
    lines.push(`    ${mode}:`, `      helder-mode: ${mode}`);
    for (const [k, v] of Object.entries(t)) lines.push(`      helder-${k}: ${q(v)}`);
    for (const [k, v] of Object.entries(haVariables(t, mode))) lines.push(`      ${k}: ${q(v)}`);
  }
  return lines.join('\n') + '\n';
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const out = new URL('../themes/helder.yaml', import.meta.url);
  writeFileSync(out, themeYaml());
  console.log('wrote', fileURLToPath(out));
}
